#!/usr/bin/env python3
"""THE WORLD - one day of world news on a single newspaper page.

Renders a 1024x1024 PNG front page summing up Sunday 22 November 2026:
a lead story, twelve more stories in a grid, a dotted world map with a
marker for every story, a by-the-numbers rail, a briefs band and a
sport footer - 23 stories from 6 continents on one page.

Pure Python 3 standard library. Text is drawn from a glyph atlas that
was rendered once (Pillow + DejaVu) and is embedded below as base64:
the atlas image is quantised to 4-bit alpha, zlib-compressed and
stored in ATLAS_B64; per-glyph metrics live in GLYPHS_B64. At runtime
the program only decodes the atlas, blits glyphs into a bytearray
framebuffer, paints simple shapes, and writes the PNG with zlib and
struct. No network, no randomness, no timestamps: every run produces
byte-identical output.

Output path: $OUTPUT if set, else $MAKEFUN_OUTPUT_DIR/entry.png if
set, else /output/entry.png when /output exists, else entry.png next
to this script.
"""

import base64
import json
import os
import struct
import zlib

W, H = 1024, 1024

PAPER = (247, 243, 234)
INK = (20, 20, 20)
NAVY = (20, 33, 61)
RED = (178, 34, 34)
GREY = (90, 86, 78)
CARD = (255, 255, 255)
LINEC = (198, 192, 180)
MAPDOT = (148, 163, 188)
MAPBG = (233, 236, 240)
BODYGREY = (60, 60, 60)
DECKDARK = (40, 40, 40)
PALE = (200, 205, 220)
BRIEFORANGE = (255, 190, 120)
BRIEFTEXT = (235, 238, 245)

LINE_H = {"mast": 55, "lead": 41, "head2": 19, "kick": 14,
          "deck": 17, "body": 15, "tiny": 13}

ATLAS_W = 1024
ATLAS_H = 381

ATLAS_B64 = (
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
)

GLYPHS_B64 = (
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    "OTMsMzcxLDYsNSw1LjkxLDAsLTVdLCJcdTIwYWMiOls5MDAsMzcxLDYsNyw2LjM2LDAsLTddfX0="
)

GLYPHS = json.loads(base64.b64decode(GLYPHS_B64).decode("utf-8"))


# ------------------------------------------------------------------
# Atlas decoding: base64 -> zlib -> packed 4-bit alpha -> 8-bit alpha
# ------------------------------------------------------------------

_packed = zlib.decompress(base64.b64decode(ATLAS_B64))
ALPHA = bytearray(ATLAS_W * ATLAS_H)
for _i in range(len(_packed)):
    _b = _packed[_i]
    ALPHA[2 * _i] = (_b >> 4) * 17
    ALPHA[2 * _i + 1] = (_b & 15) * 17
del _packed, _i, _b

# Framebuffer: one bytearray, three bytes (R, G, B) per pixel.
FB = bytearray(bytes(PAPER) * (W * H))


def fill_rect(x, y, w, h, colour):
    """Paint a solid rectangle, clipped to the page."""
    x0 = max(0, int(x))
    y0 = max(0, int(y))
    x1 = min(W, int(x) + int(w))
    y1 = min(H, int(y) + int(h))
    if x1 <= x0 or y1 <= y0:
        return
    row = bytes(colour) * (x1 - x0)
    for yy in range(y0, y1):
        off = (yy * W + x0) * 3
        FB[off:off + len(row)] = row


def circle(cx, cy, r, colour):
    """Paint a filled circle centred on (cx, cy)."""
    cx = int(round(cx))
    cy = int(round(cy))
    r = int(r)
    for dy in range(-r, r + 1):
        span = int((r * r - dy * dy) ** 0.5)
        fill_rect(cx - span, cy + dy, 2 * span + 1, 1, colour)


def glyph_for(style, ch):
    g = GLYPHS[style].get(ch)
    if g is None:
        g = GLYPHS[style]["?"]
    return g


def text_w(text, style):
    """Width in pixels of a string in the given style."""
    total = 0.0
    for ch in text:
        total += glyph_for(style, ch)[4]
    return total


def draw_text(text, style, colour, x, baseline):
    """Draw one line of text with its baseline at the given y.

    Each glyph bitmap goes to (pen + xoff, baseline + yoff) and the
    pen advances by the glyph advance. Returns the final pen x.
    """
    pen = float(x)
    cr, cg, cb = colour
    for ch in text:
        gx, gy, gw, gh, adv, xoff, yoff = glyph_for(style, ch)
        dx = int(round(pen + xoff))
        dy = int(baseline) + int(yoff)
        for row in range(gh):
            yy = dy + row
            if yy < 0 or yy >= H:
                continue
            arow = (gy + row) * ATLAS_W + gx
            frow = (yy * W) * 3
            for col in range(gw):
                xx = dx + col
                if xx < 0 or xx >= W:
                    continue
                a = ALPHA[arow + col]
                if a == 0:
                    continue
                off = frow + xx * 3
                if a == 255:
                    FB[off] = cr
                    FB[off + 1] = cg
                    FB[off + 2] = cb
                else:
                    inv = 255 - a
                    FB[off] = (cr * a + FB[off] * inv) // 255
                    FB[off + 1] = (cg * a + FB[off + 1] * inv) // 255
                    FB[off + 2] = (cb * a + FB[off + 2] * inv) // 255
        pen += adv
    return pen


def draw_text_right(text, style, colour, right_x, baseline):
    """Draw one line of text ending at right_x."""
    return draw_text(text, style, colour,
                     right_x - text_w(text, style), baseline)


def wrap(text, style, width):
    """Greedy word wrap: split text into lines that fit width."""
    lines = []
    cur = ""
    for word in text.split():
        trial = word if not cur else cur + " " + word
        if cur and text_w(trial, style) > width:
            lines.append(cur)
            cur = word
        else:
            cur = trial
    if cur:
        lines.append(cur)
    return lines


def draw_block(text, style, colour, x, first_baseline, width,
               max_lines, line_h):
    """Wrap and draw a paragraph; returns the next free baseline."""
    lines = wrap(text, style, width)[:max_lines]
    for i, line in enumerate(lines):
        draw_text(line, style, colour, x, first_baseline + i * line_h)
    return first_baseline + len(lines) * line_h


# ------------------------------------------------------------------
# PNG output (struct + zlib only)
# ------------------------------------------------------------------

def _chunk(tag, data):
    return (struct.pack(">I", len(data)) + tag + data
            + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF))


def write_png(path):
    raw = bytearray()
    stride = W * 3
    for yy in range(H):
        raw.append(0)
        raw += FB[yy * stride:(yy + 1) * stride]
    ihdr = struct.pack(">IIBBBBB", W, H, 8, 2, 0, 0, 0)
    png = (b"\x89PNG\r\n\x1a\n"
           + _chunk(b"IHDR", ihdr)
           + _chunk(b"IDAT", zlib.compress(bytes(raw), 9))
           + _chunk(b"IEND", b""))
    with open(path, "wb") as f:
        f.write(png)


def out_path():
    """Where the PNG goes, in the documented priority order."""
    if os.environ.get("OUTPUT"):
        return os.environ["OUTPUT"]
    folder = os.environ.get("MAKEFUN_OUTPUT_DIR")
    if folder:
        return os.path.join(folder, "entry.png")
    if os.path.isdir("/output"):
        return "/output/entry.png"
    here = os.path.dirname(os.path.abspath(__file__))
    return os.path.join(here, "entry.png")


