def draw_map(x, y, w, h):
    """Dotted world map with one red marker per story location."""
    fill_rect(x, y, w, h, MAPBG)
    cell_w = w / 112.0
    cell_h = h / 41.0
    radius = max(1, int(cell_w * 0.32))
    for row, first, last in MAP_RUNS:
        cy = y + (row + 0.5) * cell_h
        for col in range(first, last + 1):
            circle(x + (col + 0.5) * cell_w, cy, radius, MAPDOT)
    for lon, lat in MARKERS:
        mx = x + (lon + 180.0) / 360.0 * w
        my = y + (80.0 - lat) / 136.0 * h
        circle(mx, my, 4, RED)
        circle(mx, my, 2, CARD)


# ------------------------------------------------------------------
# Page layout
# ------------------------------------------------------------------

M = 36
CW = 952
RIGHT_EDGE = M + CW


def draw_masthead():
    fill_rect(0, 0, W, 96, NAVY)
    draw_text("THE WORLD", "mast", CARD, M, 58)
    draw_text("One day, one page - the stories that defined it",
              "deck", PALE, M, 84)
    draw_text_right(DATELINE, "kick", CARD, RIGHT_EDGE, 34)
    draw_text_right(TAGLINE, "tiny", PALE, RIGHT_EDGE, 56)
    fill_rect(0, 96, W, 5, RED)


def draw_lead():
    ly = 116
    kicker, headline, deck, body = LEAD
    draw_text(kicker.upper(), "kick", RED, M, ly + 11)
    head_next = draw_block(headline, "lead", INK, M, ly + 52, 596,
                           3, 40)
    deck_first = head_next + 6 - 40 + 18
    deck_next = draw_block(deck, "deck", DECKDARK, M, deck_first,
                           596, 2, 18)
    body_first = deck_next + 4 - 18 + LINE_H["body"]
    draw_block(body, "body", BODYGREY, M, body_first, 596, 5, 15)


def draw_rail():
    ly = 116
    rx, rw = 664, 324
    draw_text("THE DAY ON THE MAP", "kick", NAVY, rx, ly + 11)
    draw_map(rx, ly + 22, rw, 168)
    draw_text(MAP_CAPTION, "tiny", GREY, rx, ly + 206)
    draw_text("BY THE NUMBERS", "kick", NAVY, rx, ly + 226)
    for i, (big, small) in enumerate(NUMBERS):
        row_y = ly + 246 + i * 27
        draw_text(big, "head2", RED, rx, row_y + 10)
        draw_block(small, "tiny", BODYGREY, rx + 86, row_y + 11,
                   rw - 86, 2, 12)


def draw_grid():
    gy = 470
    fill_rect(M, gy - 8, CW, 1, LINEC)
    colw = (CW - 40) // 3
    for idx, (kicker, headline, body) in enumerate(STORIES):
        cx = M + (idx % 3) * (colw + 20)
        cy = gy + (idx // 3) * 104
        if idx % 3:
            fill_rect(cx - 10, cy + 2, 1, 90, LINEC)
        draw_text(kicker.upper(), "kick", RED, cx, cy + 11)
        head_next = draw_block(headline, "head2", INK, cx, cy + 35,
                               colw, 2, 19)
        draw_block(body, "body", BODYGREY, cx, head_next + 1,
                   colw, 2, 15)


def draw_briefs():
    by = 894
    fill_rect(M, by, CW, 84, NAVY)
    draw_text("AROUND THE WORLD IN BRIEF", "kick", CARD, 50, by + 22)
    bw = (CW - 28 - 32) // 3
    for i, (place, text) in enumerate(BRIEFS):
        bx = 50 + (i % 3) * (bw + 16)
        item_y = by + 44 + (i // 3) * 15
        label = place.upper() + " "
        draw_text(label, "tiny", BRIEFORANGE, bx, item_y)
        label_w = text_w(label, "tiny")
        lines = wrap(text, "tiny", bw - label_w)
        if lines:
            draw_text(lines[0], "tiny", BRIEFTEXT, bx + label_w,
                      item_y)


def draw_footer():
    fy = 990
    draw_text("SPORT", "kick", RED, M, fy + 12)
    draw_text(SPORT, "head2", INK, 94, fy + 13)
    draw_text_right(CREDITS, "tiny", GREY, RIGHT_EDGE, fy + 12)


def main():
    draw_masthead()
    draw_lead()
    draw_rail()
    draw_grid()
    draw_briefs()
    draw_footer()
    write_png(out_path())


if __name__ == "__main__":
    main()
